"""Android device support: wire-format contract (generated by the Kotlin unit tests), registration, authenticated telemetry,
Fleet/device details, sync-interval-aware staleness, battery health, tenant isolation - plus desktop-collector regression.
The app's HTTP behaviour is reproduced from its generated samples; behaviour on a physical phone is NOT covered here."""
import copy
import json
import time
import uuid
from pathlib import Path

import pytest

from common.schema import filter_event, utc_iso, validate_heartbeat
from .conftest import BASE, wait_until
from .test_remote_ngrok import CODE, XFP, Remote

CONTRACT = BASE / "android" / "contract"


@pytest.fixture(scope="module")
def srv():
    r = Remote()
    yield r
    r.close()


def load(name):
    return json.loads((CONTRACT / name).read_text())


def payload_from_sample(cid, seq, ts, battery=None, charging=None, only=None):
    """The Kotlin-generated payload with fresh ids/time (and optionally overridden battery values)."""
    p = load("payload-sample.json")
    p["payload_id"], p["collector_id"], p["seq"], p["sent_at"] = str(uuid.uuid4()), cid, seq, utc_iso(ts)
    keep = []
    for e in p["events"]:
        e["event_id"], e["event_time"] = str(uuid.uuid4()), utc_iso(ts)
        if e["metric"] == "battery_percent" and battery is not None:
            e["value"] = battery
        if e["metric"] == "battery_charging" and charging is not None:
            e["value"] = 1.0 if charging else 0.0
        if only is None or e["metric"] in only:
            keep.append(e)
    p["events"] = keep
    return p


def hb_from_sample(cid, **over):
    h = load("heartbeat-sample.json")
    h["collector_id"], h["sent_at"] = cid, utc_iso(time.time())
    h.update(over)
    return h


def reg(srv, name, install_id, code=CODE):
    body = {"device_name": name, "join_code": code}
    if install_id:
        body["install_id"] = install_id
    return srv.pub.post("/api/ingest/v1/register", json=body, headers=XFP)


def auth(key):
    return {**XFP, "Authorization": "Bearer " + key}


# ------------------------------------------------------------------------------------------- contract
def test_kotlin_generated_payload_conforms_to_server_schema():
    p = load("payload-sample.json")
    assert set(p) == {"payload_id", "collector_id", "seq", "sent_at", "schema_version", "events"}
    assert p["events"], "sample has events"
    for e in p["events"]:
        r = filter_event(e)
        assert not r["blocked"] and not r["blocked_fields"] and not r["redactions"] and not r["violations"], (e, r)
    metrics = {e["metric"] for e in p["events"]}
    assert metrics == {"memory_percent", "disk_percent", "battery_percent", "battery_charging", "bandwidth_mbps", "latency_ms"}
    assert not any("cpu" in m for m in metrics), "Android does not expose system CPU; the app must not fake it"
    assert validate_heartbeat(load("heartbeat-sample.json")) == []


# ------------------------------------------------------------------------------------------- registration
def test_android_registration_uses_existing_api_and_unique_names(srv):
    iid = str(uuid.uuid4())
    r = reg(srv, "Pixel 7", iid)
    assert r.status_code == 200
    j = r.json()
    assert j["collector_id"] == "col-r-pixel-7" and j["slug"] == "pixel-7" and j["api_key"].startswith("sx_")
    srv.pixel = {"cid": j["collector_id"], "key": j["api_key"], "iid": iid}
    # the same phone reconnecting keeps its fleet entry and rotates its key
    j2 = reg(srv, "Pixel 7", iid).json()
    assert j2["collector_id"] == j["collector_id"] and j2["api_key"] != j["api_key"]
    srv.pixel["key"] = j2["api_key"]
    # a different device must not take over the name (409), with or without an install id
    assert reg(srv, "Pixel 7", str(uuid.uuid4())).status_code == 409
    assert reg(srv, "Pixel 7", None).status_code == 409
    # a legacy laptop's name cannot be taken by a phone either
    assert reg(srv, "Work Laptop", None).status_code == 200
    assert reg(srv, "Work Laptop", str(uuid.uuid4())).status_code == 409
    assert reg(srv, "Work Laptop", None).status_code == 200, "legacy laptop reconnect still works"
    # validation + join code
    assert reg(srv, "Bad", "short").status_code == 400
    assert reg(srv, "Pixel 8", str(uuid.uuid4()), code="wrong").status_code == 403


# ------------------------------------------------------------------------------------------- telemetry + fleet
def test_authenticated_telemetry_appears_in_fleet_with_android_platform(srv):
    cid, key = srv.pixel["cid"], srv.pixel["key"]
    now = time.time()
    # authentication
    assert srv.pub.post("/api/ingest/v1/heartbeat", json=hb_from_sample(cid), headers=XFP).status_code == 401
    assert srv.pub.post("/api/ingest/v1/heartbeat", json=hb_from_sample(cid), headers=auth("sx_wrong")).status_code == 401
    assert srv.pub.post("/api/ingest/v1/payload", json=payload_from_sample(cid, 1, now), headers=XFP).status_code == 401
    # heartbeat, then a payload built like the app builds it
    assert srv.pub.post("/api/ingest/v1/heartbeat", json=hb_from_sample(cid), headers=auth(key)).status_code == 200
    p = payload_from_sample(cid, 1, now)
    r = srv.pub.post("/api/ingest/v1/payload", json=p, headers=auth(key))
    assert r.status_code == 200 and r.json()["status"] == "accepted" and r.json()["accepted_events"] == 6
    # idempotent retry (lost response): same payload_id is acknowledged but not stored twice
    r2 = srv.pub.post("/api/ingest/v1/payload", json=p, headers=auth(key))
    assert r2.status_code == 200 and r2.json()["status"] == "duplicate"
    # extra fields are still refused (allow-list is unchanged for phones)
    bad = payload_from_sample(cid, 2, now)
    bad["events"][0]["imei"] = "356938035643809"
    assert srv.pub.post("/api/ingest/v1/payload", json=bad, headers=auth(key)).status_code == 422
    assert srv.pub.post("/api/ingest/v1/heartbeat", json=hb_from_sample(cid, imei="1234"), headers=auth(key)).status_code == 422

    adm = srv.admin()
    fleet = {c["id"]: c for c in srv.dash.get("/api/collectors", headers=adm).json()}
    ph = fleet[cid]
    assert ph["platform"] == "android" and ph["device_model"] == "Google Pixel 7" and ph["os_version"] == "Android 14 (API 34)"
    assert ph["status"] == "online" and ph["interval_s"] == 900
    assert "key_hash" not in ph and "install_id" not in ph
    # device details: RAM, storage, battery + charging, network
    d = srv.dash.get(f"/api/collectors/{cid}", headers=adm).json()
    got = {m["metric"]: m for m in d["metrics"]}
    assert set(got) == {"memory_percent", "disk_percent", "battery_percent", "battery_charging", "bandwidth_mbps", "latency_ms"}
    assert got["battery_percent"]["value"] == 83.0 and got["battery_charging"]["value"] == 1.0
    assert got["memory_percent"]["source_id"] == "host:pixel-7" and got["bandwidth_mbps"]["source_id"] == "net:pixel-7-link"
    assert "install_id" not in json.dumps(d) and "key_hash" not in json.dumps(d)
    # entities show up with the other devices on the dashboard overview
    ov = srv.dash.get("/api/overview", headers=adm).json()
    assert {"host:pixel-7", "net:pixel-7-link"} <= {e["id"] for e in ov["entities"]}


def test_auth_rotation_and_tenant_isolation(srv):
    cid = srv.pixel["cid"]
    old = srv.pixel["key"]
    assert reg(srv, "Pixel 7", srv.pixel["iid"]).status_code == 200      # rotates
    assert srv.pub.post("/api/ingest/v1/heartbeat", json=hb_from_sample(cid), headers=auth(old)).status_code == 401
    # another tenant sees nothing of this phone
    t = srv.dash.post("/api/login", json={"username": "globex-admin", "password": "Globex#Admin2026"}).json()["token"]
    g = {"Authorization": "Bearer " + t}
    assert cid not in {c["id"] for c in srv.dash.get("/api/collectors", headers=g).json()}
    assert srv.dash.get(f"/api/collectors/{cid}", headers=g).status_code == 404
    assert srv.dash.get(f"/api/collectors/{cid}").status_code == 401
    assert "host:pixel-7" not in {e["id"] for e in srv.dash.get("/api/overview", headers=g).json()["entities"]}
    # a phone's key cannot be used for a different collector id
    new = reg(srv, "Pixel 7", srv.pixel["iid"]).json()["api_key"]
    srv.pixel["key"] = new
    other = reg(srv, "Other Phone", str(uuid.uuid4())).json()
    assert srv.pub.post("/api/ingest/v1/payload", json=payload_from_sample(other["collector_id"], 1, time.time()), headers=auth(new)).status_code == 422


# ------------------------------------------------------------------------------------------- staleness scaling
def test_phone_with_15_min_interval_is_not_offline_after_30s_but_a_laptop_is(srv):
    ph = srv.pixel
    lap = reg(srv, "Work Laptop", None).json()
    assert srv.pub.post("/api/ingest/v1/heartbeat", json=hb_from_sample(ph["cid"], interval_s=900.0), headers=auth(ph["key"])).status_code == 200
    lh = hb_from_sample(lap["collector_id"], platform="windows", os_version="Windows 11")
    lh.pop("device_model"); lh.pop("interval_s")
    assert srv.pub.post("/api/ingest/v1/heartbeat", json=lh, headers=auth(lap["api_key"])).status_code == 200
    adm = srv.admin()
    time.sleep(36)    # > offline_after_s (30 s)
    fleet = {c["id"]: c for c in srv.dash.get("/api/collectors", headers=adm).json()}
    assert fleet[ph["cid"]]["status"] == "online" and fleet[ph["cid"]]["state"] != "Poor", fleet[ph["cid"]]
    assert fleet[lap["collector_id"]]["status"] == "offline" and fleet[lap["collector_id"]]["state"] == "Poor", "laptops keep 30 s semantics"
    assert fleet[lap["collector_id"]]["platform"] == "windows"
    # a phone that skips far more than 4 sync intervals does go offline (tested via a short declared interval)
    assert srv.pub.post("/api/ingest/v1/heartbeat", json=hb_from_sample(ph["cid"], interval_s=5.0), headers=auth(ph["key"])).status_code == 200


# ------------------------------------------------------------------------------------------- battery health
def test_battery_is_lower_is_worse_and_ignored_while_charging(srv):
    cid, key = srv.pixel["cid"], srv.pixel["key"]
    adm = srv.admin()
    seq = [100]

    def send(ts, battery, charging, only=("battery_percent", "battery_charging")):
        seq[0] += 1
        r = srv.pub.post("/api/ingest/v1/payload", json=payload_from_sample(cid, seq[0], ts, battery=battery, charging=charging, only=only), headers=auth(key))
        assert r.status_code == 200, r.text

    def bat_state():
        e = next(e for e in srv.dash.get("/api/overview", headers=adm).json()["entities"] if e["id"] == "host:pixel-7")
        return e["metrics"]["battery_percent"]["state"], e["metrics"]["battery_percent"].get("reason")

    t = time.time()
    send(t, 85.0, False)
    assert bat_state()[0] == "Excellent"
    send(t + 1, 35.0, False)
    assert bat_state()[0] == "Good"
    send(t + 2, 15.0, False)
    st, why = bat_state()
    assert st == "Fair" and "warning" in why
    send(t + 3, 8.0, False)
    assert bat_state()[0] == "Poor"
    al = [a for a in srv.dash.get("/api/alerts?limit=50", headers=adm).json() if a["metric"] == "battery_percent" and a["cleared_ms"] is None]
    assert al and al[0]["severity"] == "critical" and "battery" in al[0]["title"]
    # plugging in: not a problem any more, and the alert clears
    send(t + 4, 8.0, True)
    for i in range(5, 11):
        send(t + i, 9.0 + i, True)
    assert bat_state()[0] == "Excellent"
    wait_until(lambda: not [a for a in srv.dash.get("/api/alerts?limit=50", headers=adm).json()
                            if a["metric"] == "battery_percent" and a["cleared_ms"] is None], 10, msg="battery alert cleared")
    # threshold editing honours lower-is-worse ordering
    ok = srv.dash.put("/api/thresholds", headers=adm, json={"thresholds": {"battery_percent": {"good_max": 50, "warn": 25, "crit": 10}}})
    assert ok.status_code == 200
    bad = srv.dash.put("/api/thresholds", headers=adm, json={"thresholds": {"battery_percent": {"good_max": 10, "warn": 25, "crit": 50}}})
    assert bad.status_code == 400 and "lower is worse" in bad.text
    srv.dash.put("/api/thresholds", headers=adm, json={"thresholds": {"battery_percent": {"good_max": 40, "warn": 20, "crit": 10}}})
    # non-battery thresholds keep their original ordering rule
    assert srv.dash.put("/api/thresholds", headers=adm, json={"thresholds": {"cpu_percent": {"good_max": 90, "warn": 80, "crit": 70}}}).status_code == 400


# ------------------------------------------------------------------------------------------- dashboard + regression
def test_dashboard_bundle_contains_platform_and_device_detail_ui():
    js = "".join(p.read_text(errors="ignore") for p in (BASE / "web" / "dist" / "assets").glob("*.js"))
    for needle in ("Platform", "Click a device for details", "Storage used", "charging", "not exposed by Android"):
        assert needle in js, needle


def test_desktop_collectors_unchanged_and_report_their_platform(stack, admin):
    def get_me():
        me = next(x for x in stack.saas.get("/api/collectors", headers=admin).json() if x["id"] == "col-acme-01")
        return me if me["status"] == "online" and me["platform"] else None
    me = wait_until(get_me, 40, 1, msg="desktop collector online with platform")
    assert me["status"] == "online" and me["platform"] in ("windows", "macos", "linux")
    assert me["os_version"] and not me["device_model"]
    def detail_with_cpu():   # the heartbeat arrives before the first telemetry payload
        d = stack.saas.get("/api/collectors/col-acme-01", headers=admin).json()
        return d if any(m["metric"] == "cpu_percent" for m in d["metrics"]) else None
    d = wait_until(detail_with_cpu, 40, 1, msg="laptop CPU metric in device details")
    assert any(m["metric"] == "cpu_percent" for m in d["metrics"]), "laptops still report CPU"
    # the unchanged desktop heartbeat contract still rejects unknown fields
    cfg = stack.cfg["acme"]
    import httpx
    tls = httpx.Client(verify=cfg["ca_cert"], base_url="https://localhost:18443", headers={"Authorization": "Bearer " + cfg["api_key"]})
    assert tls.post("/api/ingest/v1/heartbeat", json={"collector_id": cfg["collector_id"], "hostname": "x"}).status_code == 422
